const muatJenisLokasi = `-- name: MuatJenisLokasi :many
SELECT id, jenis::text AS jenis
FROM inv_lokasi_stok
WHERE id = ANY($1::bigint[])
`

type MuatJenisLokasiRow struct {
	ID    int64  `json:"id"`
	Jenis string `json:"jenis"`
}

// Jenis lokasi TANPA filter deleted (verbatim valuasi PENYESUAIAN).
func (q *Queries) MuatJenisLokasi(ctx context.Context, ids []int64) ([]MuatJenisLokasiRow, error) {
	rows, err := q.db.Query(ctx, muatJenisLokasi, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []MuatJenisLokasiRow
	for rows.Next() {
		var i MuatJenisLokasiRow
		if err := rows.Scan(&i.ID, &i.Jenis); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

